import sys

def parse_traceback(text):
    frames = []
    exception = None
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("File \""):
            parts = line.split(", ")
            path = parts[0].split("\"")[1]
            lineno = int(parts[1].replace("line ", ""))
            frames.append((path, lineno))
        elif line and not line.startswith("Traceback"):
            exception = line.split(":")[0]
    return exception, (frames[-1] if frames else (None, None))

if __name__ == "__main__":
    exc, (path, lineno) = parse_traceback(sys.stdin.read())
    print(exc, path, lineno)
